 ($q$EFFICIENCY TEST 7$q$, $q${"schemaVersion":"1","language":"Hindi","paragraphs":[{"id":"matter-p-1","type":"paragraph","paragraphNumber":1,"listGroup":null,"runs":[{"text":"dEI;wVj vkt gekjs thou dk ,d egRoiw.kZ vax cu x;k gSA cSad] jsyos] vLirky vkSj ljdkjh dk;kZy;ksa esa vf/kdrj dke dEI;wVj dh lgk;rk ls rst+h ls fd, tkrs gSaA jktLFkku deZpkjh p;u cksMZ dh ijh{kkvksa esa Hkh dEI;wVj dk Kku vko';d gSA tks vH;FkhZ fu;fer vH;kl djrs gSa] os Vkbfiax vkSj n{krk ijh{kk esa vPNs vad izkIr djrs gSaA","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":14,"fontFamily":"Kruti Dev 010"}],"alignment":"justify","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-2","type":"paragraph","paragraphNumber":2,"listGroup":null,"runs":[{"text":"Microsoft Word is a word processing program that helps you create a professional document in a short time. You can type text, format it, insert pictures and tables, and save your document on the computer or in the cloud. A well formatted document is easy to read and looks attractive.","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-3","type":"paragraph","paragraphNumber":3,"listGroup":null,"runs":[{"text":"Typing speed and accuracy are both important in an efficiency test. Read every question carefully, select the correct text and use the right option from the ribbon. Do not press Enter at the end of every line, because Word moves the text to the next line by itself.","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-4","type":"paragraph","paragraphNumber":4,"listGroup":null,"runs":[{"text":"The Home tab contains the most used commands of Word, such as the Font, Paragraph and Editing groups. The Insert tab is used to add pages, tables, headers, footers and symbols to a document.","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-5","type":"list-item","paragraphNumber":5,"listGroup":"list-1","runs":[{"text":"Home Tab","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8,"numbered":false},{"id":"matter-p-6","type":"list-item","paragraphNumber":6,"listGroup":"list-1","runs":[{"text":"Insert Tab","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8,"numbered":false},{"id":"matter-p-7","type":"list-item","paragraphNumber":7,"listGroup":"list-1","runs":[{"text":"Design Tab","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8,"numbered":false},{"id":"matter-p-8","type":"list-item","paragraphNumber":8,"listGroup":"list-1","runs":[{"text":"Page Layout Tab","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8,"numbered":false},{"id":"matter-p-9","type":"paragraph","paragraphNumber":9,"listGroup":null,"runs":[{"text":"Einstein's famous formula is E = mc2","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-10","type":"paragraph","paragraphNumber":10,"listGroup":null,"runs":[{"text":"Samradhi Classes, Jaipur","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-11","type":"table","rows":[["S.No.","Name","City","Marks"],["1","Rakesh","Jaipur","68"],["2","Sunita","Ajmer","82"],["3","Mahesh","Kota","55"],["4","Pooja","Bikaner","91"],["5","Anil","Udaipur","74"]],"cellFonts":[["Segoe UI","Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI","Segoe UI"]],"cellSizes":[[12,12,12,12],[12,12,12,12],[12,12,12,12],[12,12,12,12],[12,12,12,12],[12,12,12,12]]},{"id":"matter-p-12","type":"paragraph","paragraphNumber":12,"listGroup":null,"runs":[{"text":"","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8}],"warnings":[],"formattingSummary":{"paragraphs":12,"runs":12,"italicParagraphs":0,"justifiedParagraphs":1,"listItems":4,"tables":1,"fonts":["Kruti Dev 010","Segoe UI"]}}$q$::jsonb, $q$[{"number":1,"instruction":"प्रथम पैराग्राफ (हिंदी) को फॉन्ट साइज 16, बोल्ड एवं फॉन्ट कलर Dark Red दीजिए।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":0,"props":{"fontSize":[16],"bold":[true],"color":["C00000"]}}],"solution":"1. पहला (हिंदी) पैराग्राफ सेलेक्ट करें।\n2. HOME → Font Size **16**, **Bold** (Ctrl+B)।\n3. **Font Color ▾** → Standard Colors में **Dark Red**।\n\nजाँच: पहला पैराग्राफ साइज 16, बोल्ड और गहरा लाल।"},{"number":2,"instruction":"द्वितीय पैराग्राफ को फॉन्ट Arial, इटैलिक एवं डबल अंडरलाइन दीजिए।","marks":1.66,"criteria":[{"rule":"words","kind":"body","place":1,"props":{"fontFamily":["Arial"],"italic":[true],"underline":[true],"underlineStyle":["double"]}}],"solution":"1. दूसरा पैराग्राफ (\"Microsoft Word is…\") सेलेक्ट करें।\n2. HOME → Font **Arial**, **Italic** (Ctrl+I)।\n3. **Underline ▾** → **Double underline** (या Font डायलॉग Ctrl+D → Underline style **Double**)।\n\nजाँच: दूसरा पैराग्राफ Arial, इटैलिक, डबल अंडरलाइन।"},{"number":3,"instruction":"चतुर्थ पैराग्राफ को Change Case से UPPERCASE कीजिए।","marks":1.66,"criteria":[{"rule":"text","kind":"body","place":3,"find":"THE HOME TAB CONTAINS THE MOST USED COMMANDS OF WORD","caseSensitive":true}],"solution":"1. चौथा पैराग्राफ (\"The Home tab contains…\") सेलेक्ट करें।\n2. HOME → **Change Case (Aa ▾)** → **UPPERCASE**।\n\nजाँच: चौथे पैराग्राफ के सभी अक्षर बड़े।"},{"number":4,"instruction":"\"E = mc2\" में 2 को सुपरस्क्रिप्ट (Superscript) कीजिए।","marks":1.66,"criteria":[{"rule":"text","kind":"body","place":8,"find":"2","props":{"superscript":[true]}}],"solution":"1. \"E = mc2\" में केवल **2** सेलेक्ट करें।\n2. HOME → **Superscript (x²)** (Ctrl+Shift+=)।\n\nजाँच: E = mc²।"},{"number":5,"instruction":"द्वितीय पैराग्राफ को Justify अलाइनमेंट एवं लाइन स्पेसिंग 1.5 दीजिए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":1,"target":"blocks.0.alignment","spec":["justify"]},{"rule":"value","kind":"body","place":1,"target":"blocks.0.attrs.lineHeight","spec":["1.5"]}],"solution":"दूसरे पैराग्राफ में क्लिक करें:\n1. HOME → **Justify** (Ctrl+J)।\n2. HOME → **Line and Paragraph Spacing ▾** → **1.5**।\n\nजाँच: जस्टिफाई और लाइन स्पेसिंग 1.5।"},{"number":6,"instruction":"दी गई सूची (Home Tab, Insert Tab…) की बुलेट्स को नंबरिंग 1. 2. 3. में बदलिए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":4,"target":"blocks.0.attrs.listStyle","spec":["decimal"]},{"rule":"value","kind":"body","place":5,"target":"blocks.0.attrs.listStyle","spec":["decimal"]},{"rule":"value","kind":"body","place":6,"target":"blocks.0.attrs.listStyle","spec":["decimal"]},{"rule":"value","kind":"body","place":7,"target":"blocks.0.attrs.listStyle","spec":["decimal"]}],"solution":"1. सूची के चारों आइटम सेलेक्ट करें।\n2. HOME → **Numbering ▾** → **1. 2. 3.**।\n\nजाँच: सूची 1. से 4. तक नंबर वाली।"},{"number":7,"instruction":"तृतीय पैराग्राफ पर Box बॉर्डर एवं Light Green शेडिंग दीजिए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":2,"target":"blocks.0.attrs.border","spec":{"regex":"^(?!.*sides:)\\S+ (solid|double|dotted|dashed)"}},{"rule":"value","kind":"body","place":2,"target":"blocks.0.attrs.backgroundColor","spec":{"regex":"92D050|rgb\\(146, ?208, ?80\\)"}}],"solution":"तीसरे पैराग्राफ में क्लिक करें:\n1. HOME → **Borders ▾** → **Borders and Shading…** → Borders: Setting **Box** → Apply to **Paragraph**।\n2. **Shading** टैब → Fill **Light Green** → Apply to **Paragraph** → **OK**।\n\nजाँच: तीसरे पैराग्राफ के चारों ओर बॉर्डर और हल्की हरी शेडिंग।"},{"number":8,"instruction":"टेबल को \"Marks\" कॉलम के अनुसार आरोही क्रम (Ascending) में सॉर्ट कीजिए।","marks":1.66,"criteria":[{"rule":"table","place":0,"headerAt":{"3":"Marks"},"sortedColumn":3}],"solution":"1. टेबल में क्लिक करें।\n2. HOME → **Sort (A↓Z)** → Sort by **Marks**, Type **Number**, **Ascending**, My list has **Header row** → **OK**।\n\nजाँच: Marks 55, 68, 74, 82, 91 के क्रम में।"},{"number":9,"instruction":"पूरे डॉक्यूमेंट में \"document\" शब्द को \"file\" शब्द से Replace All कीजिए।","marks":1.66,"criteria":[{"rule":"text","kind":"body","find":"document","minCount":0,"maxCount":0},{"rule":"text","kind":"body","find":"file","wholeWord":true,"minCount":4}],"solution":"1. HOME → **Replace** (Ctrl+H)।\n2. Find what **document**, Replace with **file** → **Replace All**।\n\nजाँच: डॉक्यूमेंट में कहीं भी \"document\" नहीं, चार जगह \"file\"।"},{"number":10,"instruction":"टेबल से ठीक पहले Page Break लगाइए, ताकि टेबल नए पेज पर आ जाए।","marks":1.66,"criteria":[{"rule":"value","kind":"body","place":10,"target":"blocks.0.type","spec":["page-break"]}],"solution":"1. \"Samradhi Classes, Jaipur\" लाइन के अंत में क्लिक करें (टेबल से ठीक पहले)।\n2. INSERT → **Page Break** (Ctrl+Enter)।\n\nजाँच: टेबल अगले पेज पर।"},{"number":11,"instruction":"डॉक्यूमेंट के अंत में (टेबल के बाद) 3 कॉलम एवं 4 रो की एक नई टेबल इन्सर्ट कीजिए।","marks":1.66,"criteria":[{"rule":"table","place":1,"columns":3,"rowCount":4}],"solution":"1. दी गई टेबल के नीचे, डॉक्यूमेंट के अंत में क्लिक करें।\n2. INSERT → **Table ▾** → **Insert Table…** → Number of columns **3**, Number of rows **4** → **OK** (या ग्रिड में 3x4)।\n\nजाँच: अंत में 3 कॉलम × 4 रो की नई टेबल।"},{"number":12,"instruction":"\"Samradhi Classes, Jaipur\" से पहले कॉपीराइट चिह्न © लगाइए।","marks":1.66,"criteria":[{"rule":"anyOf","criteria":[{"rule":"text","kind":"body","place":9,"find":"© Samradhi"},{"rule":"text","kind":"body","place":9,"find":"©Samradhi"}]}],"solution":"1. \"Samradhi Classes, Jaipur\" के आरंभ में क्लिक करें।\n2. INSERT → **Symbol ▾** → **©** (या More Symbols… → Special Characters → **Copyright**) → Insert।\n\nजाँच: © Samradhi Classes, Jaipur।"},{"number":13,"instruction":"हेडर में \"RSSB LDC EXAM - 2026\" लिखिए एवं फूटर में दाईं ओर पेज नंबर लगाइए।","marks":1.66,"criteria":[{"rule":"text","kind":"header","find":"RSSB LDC EXAM - 2026"},{"rule":"run","kind":"footer","props":{"field":{"regex":"^page-number\\|.*\\|right$"}}}],"solution":"1. INSERT → **Header ▾** → **Edit Header** → टाइप करें **RSSB LDC EXAM - 2026**।\n2. INSERT → **Page Number ▾** → **Bottom of Page** → **Plain Number 3** (दाईं ओर)।\n3. **Close Header and Footer**।\n\nजाँच: हेडर में टेक्स्ट, फूटर में दाईं ओर पेज नंबर।"},{"number":14,"instruction":"पेज पर Box पेज बॉर्डर दीजिए, जिसकी लाइन Double एवं कलर Blue हो।","marks":1.66,"criteria":[{"rule":"value","target":"pageLayout.border","spec":{"regex":"^(?!.*sides:)\\S+ double (#0070C0|rgb\\(0, ?112, ?192\\))"}}],"solution":"1. DESIGN → **Page Borders**।\n2. Setting **Box**, Style **डबल लाइन (═)**, Color **Blue** → Apply to **Whole document** → **OK**।\n\nजाँच: पूरे पेज के चारों ओर नीली डबल लाइन।"},{"number":15,"instruction":"पेज का Orientation Landscape एवं Margins Narrow कीजिए।","marks":1.76,"criteria":[{"rule":"value","target":"pageLayout.aspectRatio","spec":{"regex":"^(29\\.7 ?/ ?21|1\\.414 ?/ ?1)$"}},{"rule":"value","target":"pageLayout.padding","spec":["12.7mm 12.7mm 12.7mm 12.7mm"]}],"solution":"1. PAGE LAYOUT → **Orientation ▾** → **Landscape**।\n2. PAGE LAYOUT → **Margins ▾** → **Narrow**।\n\nजाँच: पेज लैंडस्केप, चारों मार्जिन 0.5\"।"}]$q$::jsonb),
 ($q$EFFICIENCY TEST 8$q$, $q${"schemaVersion":"1","language":"Hindi","paragraphs":[{"id":"matter-p-1","type":"paragraph","paragraphNumber":1,"listGroup":null,"runs":[{"text":"jktLFkku viuh le`) laLÑfr] ,sfrgkfld fdyksa vkSj jax&fcjaxs R;ksgkjksa ds fy, iwjs fo'o esa izfl) gSA t;iqj] tks/kiqj] mn;iqj vkSj tSlyesj tSls 'kgj gj o\"kZ yk[kksa i;ZVdksa dks vkdf\"kZr djrs gSaA ;gk¡ ds yksx vfrfFk dk lEeku djrs gSa vkSj viuh ijaijkvksa dks vkt Hkh l¡Hkkydj j[krs gSaA","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":14,"fontFamily":"Kruti Dev 010"}],"alignment":"justify","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-2","type":"paragraph","paragraphNumber":2,"listGroup":null,"runs":[{"text":"Practice is the key to success in any computer examination. A student who practises daily learns the shortcut keys, understands the ribbon and completes the paper well before the time is over. Regular practice also reduces mistakes and builds confidence.","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-3","type":"paragraph","paragraphNumber":3,"listGroup":null,"runs":[{"text":"Samradhi Classes prepares students for typing, stenography and computer efficiency tests. Samradhi Classes provides practice papers that are similar to the real examination, so that every student knows exactly what to expect.","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-4","type":"paragraph","paragraphNumber":4,"listGroup":null,"runs":[{"text":"Formatting changes the look of a page without changing its words. Good formatting uses a clear font, proper spacing and correct alignment, and it helps the reader to understand the main points quickly.","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-5","type":"list-item","paragraphNumber":5,"listGroup":"list-1","runs":[{"text":"Read the question","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8,"numbered":false},{"id":"matter-p-6","type":"list-item","paragraphNumber":6,"listGroup":"list-1","runs":[{"text":"Select the text","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8,"numbered":false},{"id":"matter-p-7","type":"list-item","paragraphNumber":7,"listGroup":"list-1","runs":[{"text":"Apply the formatting","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8,"numbered":false},{"id":"matter-p-8","type":"list-item","paragraphNumber":8,"listGroup":"list-1","runs":[{"text":"Check your work","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8,"numbered":false},{"id":"matter-p-9","type":"paragraph","paragraphNumber":9,"listGroup":null,"runs":[{"text":"The chemical formula of sulphuric acid is H2SO4","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-10","type":"paragraph","paragraphNumber":10,"listGroup":null,"runs":[{"text":"Samradhi Classes is a registered name","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8},{"id":"matter-p-11","type":"table","rows":[["Course","Duration","Fee"],["Typing","3 Months","3000"],["Stenography","6 Months","6000"],["Computer","2 Months","2500"],["Tally","3 Months","4000"]],"cellFonts":[["Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI"],["Segoe UI","Segoe UI","Segoe UI"]],"cellSizes":[[12,12,12],[12,12,12],[12,12,12],[12,12,12],[12,12,12]]},{"id":"matter-p-12","type":"paragraph","paragraphNumber":12,"listGroup":null,"runs":[{"text":"","bold":false,"italic":false,"underline":false,"strike":false,"color":null,"highlight":null,"fontSize":12,"fontFamily":"Segoe UI"}],"alignment":"left","leftIndent":0,"rightIndent":0,"lineSpacing":1.15,"spaceBefore":0,"spaceAfter":8}],"warnings":[],"formattingSummary":{"paragraphs":12,"runs":12,"italicParagraphs":0,"justifiedParagraphs":1,"listItems":4,"tables":1,"fonts":["Kruti Dev 010","Segoe UI"]}}$q$::jsonb, $q$[{"number":1,"instruction":"प्रथम पैराग्राफ (हिंदी) को फॉन्ट साइज 15, इटैलिक एवं फॉन्ट कलर Blue दीजिए।","marks":1.56,"criteria":[{"rule":"words","kind":"body","place":0,"props":{"fontSize":[15],"italic":[true],"color":["0070C0"]}}],"solution":"1. पहला (हिंदी) पैराग्राफ सेलेक्ट करें।\n2. HOME → Font Size **15**, **Italic** (Ctrl+I)।\n3. **Font Color ▾** → Standard Colors में **Blue**।\n\nजाँच: पहला पैराग्राफ साइज 15, इटैलिक, नीला।"},{"number":2,"instruction":"द्वितीय पैराग्राफ को फॉन्ट Times New Roman एवं फॉन्ट साइज 13 दीजिए।","marks":1.56,"criteria":[{"rule":"words","kind":"body","place":1,"props":{"fontFamily":["Times New Roman"],"fontSize":[13]}}],"solution":"1. दूसरा पैराग्राफ (\"Practice is the key…\") सेलेक्ट करें।\n2. HOME → Font **Times New Roman**, Font Size बॉक्स में **13** टाइप करके Enter।\n\nजाँच: दूसरा पैराग्राफ Times New Roman, 13।"},{"number":3,"instruction":"\"H2SO4\" में सभी अंकों (2 एवं 4) को सबस्क्रिप्ट (Subscript) कीजिए।","marks":1.56,"criteria":[{"rule":"text","kind":"body","place":8,"find":"2","props":{"subscript":[true]}},{"rule":"text","kind":"body","place":8,"find":"4","props":{"subscript":[true]}}],"solution":"1. \"H2SO4\" में **2** सेलेक्ट करें → HOME → **Subscript (x₂)** (Ctrl+=)।\n2. इसी तरह **4** को भी सबस्क्रिप्ट करें।\n\nजाँच: H₂SO₄।"},{"number":4,"instruction":"तृतीय पैराग्राफ में दोनों \"Samradhi Classes\" को बोल्ड एवं पीले (Yellow) रंग से हाइलाइट कीजिए।","marks":1.56,"criteria":[{"rule":"text","kind":"body","place":2,"find":"Samradhi Classes","minCount":2,"props":{"bold":[true],"highlight":["FFFF00"]}}],"solution":"1. तीसरे पैराग्राफ में पहला \"Samradhi Classes\" सेलेक्ट करें → HOME → **Bold** और **Text Highlight Color ▾** → **Yellow**।\n2. दूसरे \"Samradhi Classes\" पर भी यही करें।\n\nजाँच: तीसरे पैराग्राफ के दोनों \"Samradhi Classes\" बोल्ड और पीले हाइलाइट में।"},{"number":5,"instruction":"चतुर्थ पैराग्राफ को Character Spacing Expanded 2 pt दीजिए।","marks":1.56,"criteria":[{"rule":"words","kind":"body","place":3,"props":{"charSpacing":[2]}}],"solution":"1. चौथा पैराग्राफ (\"Formatting changes…\") सेलेक्ट करें।\n2. HOME → Font ग्रुप **↘** (Ctrl+D) → **Advanced** → Spacing **Expanded**, By **2 pt** → **OK**।\n\nजाँच: चौथे पैराग्राफ के अक्षरों में 2 pt का फैलाव।"},{"number":6,"instruction":"द्वितीय पैराग्राफ को Center अलाइनमेंट एवं लाइन स्पेसिंग 2.0 दीजिए।","marks":1.56,"criteria":[{"rule":"value","kind":"body","place":1,"target":"blocks.0.alignment","spec":["center"]},{"rule":"value","kind":"body","place":1,"target":"blocks.0.attrs.lineHeight","spec":{"regex":"^2(\\.0+)?$"}}],"solution":"दूसरे पैराग्राफ में क्लिक करें:\n1. HOME → **Center** (Ctrl+E)।\n2. HOME → **Line and Paragraph Spacing ▾** → **2.0**।\n\nजाँच: दूसरा पैराग्राफ बीच में, लाइन स्पेसिंग 2.0।"},{"number":7,"instruction":"तृतीय पैराग्राफ में First Line इंडेंट 0.5\" दीजिए।","marks":1.56,"criteria":[{"rule":"value","kind":"body","place":2,"target":"blocks.0.attrs.specialIndentMode","spec":["firstLine"]},{"rule":"value","kind":"body","place":2,"target":"blocks.0.attrs.specialIndentAmount","spec":{"regex":"^(0\\.5in|36pt|0\\.5\")$"}}],"solution":"1. तीसरे पैराग्राफ में क्लिक करें।\n2. HOME → Paragraph ग्रुप **↘** → Indentation Special **First line**, By **0.5\"** → **OK**।\n\nजाँच: तीसरे पैराग्राफ की पहली लाइन 0.5\" अंदर।"},{"number":8,"instruction":"दी गई सूची (Read the question…) की बुलेट्स को रोमन नंबरिंग I. II. III. में बदलिए।","marks":1.56,"criteria":[{"rule":"value","kind":"body","place":4,"target":"blocks.0.attrs.listStyle","spec":["upper-roman"]},{"rule":"value","kind":"body","place":5,"target":"blocks.0.attrs.listStyle","spec":["upper-roman"]},{"rule":"value","kind":"body","place":6,"target":"blocks.0.attrs.listStyle","spec":["upper-roman"]},{"rule":"value","kind":"body","place":7,"target":"blocks.0.attrs.listStyle","spec":["upper-roman"]}],"solution":"1. सूची के चारों आइटम सेलेक्ट करें।\n2. HOME → **Numbering ▾** → Numbering Library में **I. II. III.**।\n\nजाँच: सूची के आगे I. से IV. तक रोमन अंक।"},{"number":9,"instruction":"टेबल को \"Course\" कॉलम के अनुसार A से Z (Ascending) क्रम में सॉर्ट कीजिए।","marks":1.56,"criteria":[{"rule":"table","place":0,"headerAt":{"0":"Course"},"sortedColumn":0}],"solution":"1. टेबल में क्लिक करें।\n2. HOME → **Sort (A↓Z)** → Sort by **Course**, Type **Text**, **Ascending**, My list has **Header row** → **OK**।\n\nजाँच: Computer, Stenography, Tally, Typing के क्रम में।"},{"number":10,"instruction":"पूरे डॉक्यूमेंट में \"practice\" शब्द को \"exercise\" शब्द से Replace All कीजिए।","marks":1.56,"criteria":[{"rule":"text","kind":"body","find":"practice","wholeWord":true,"minCount":0,"maxCount":0},{"rule":"text","kind":"body","find":"exercise","wholeWord":true,"minCount":3}],"solution":"1. HOME → **Replace** (Ctrl+H)।\n2. Find what **practice**, Replace with **exercise** → **More >>** → **Find whole words only** ✔ → **Replace All**।\n\nजाँच: \"practice\" की जगह तीन जगह \"exercise\" (\"practises\" नहीं बदलता)।"},{"number":11,"instruction":"टेबल से ठीक पहले Page Break लगाइए, ताकि टेबल नए पेज पर आ जाए।","marks":1.56,"criteria":[{"rule":"value","kind":"body","place":10,"target":"blocks.0.type","spec":["page-break"]}],"solution":"1. \"Samradhi Classes is a registered name\" लाइन के अंत में क्लिक करें (टेबल से ठीक पहले)।\n2. INSERT → **Page Break** (Ctrl+Enter)।\n\nजाँच: टेबल अगले पेज पर।"},{"number":12,"instruction":"डॉक्यूमेंट के अंत में (टेबल के बाद) 2 कॉलम एवं 5 रो की एक नई टेबल इन्सर्ट कीजिए।","marks":1.56,"criteria":[{"rule":"table","place":1,"columns":2,"rowCount":5}],"solution":"1. दी गई टेबल के नीचे, डॉक्यूमेंट के अंत में क्लिक करें।\n2. INSERT → **Table ▾** → **Insert Table…** → Number of columns **2**, Number of rows **5** → **OK**।\n\nजाँच: अंत में 2 कॉलम × 5 रो की नई टेबल।"},{"number":13,"instruction":"\"Samradhi Classes is a registered name\" में \"Classes\" के ठीक बाद Registered चिह्न ® लगाइए।","marks":1.56,"criteria":[{"rule":"anyOf","criteria":[{"rule":"text","kind":"body","place":9,"find":"Classes®"},{"rule":"text","kind":"body","place":9,"find":"Classes ®"}]}],"solution":"1. \"Samradhi Classes is a registered name\" में \"Classes\" के ठीक बाद क्लिक करें।\n2. INSERT → **Symbol ▾** → **®** (या More Symbols… → Special Characters → **Registered**) → Insert।\n\nजाँच: Samradhi Classes® is a registered name।"},{"number":14,"instruction":"फूटर में बाईं ओर \"Samradhi Classes\" लिखिए एवं हेडर में बीच में (Center) पेज नंबर लगाइए।","marks":1.56,"criteria":[{"rule":"text","kind":"footer","find":"Samradhi Classes"},{"rule":"run","kind":"header","props":{"field":{"regex":"^page-number\\|.*\\|center$"}}}],"solution":"1. INSERT → **Footer ▾** → **Edit Footer** → बाईं ओर टाइप करें **Samradhi Classes**।\n2. INSERT → **Page Number ▾** → **Top of Page** → **Plain Number 2** (बीच में)।\n3. **Close Header and Footer**।\n\nजाँच: फूटर में बाईं ओर टेक्स्ट, हेडर के बीच में पेज नंबर।"},{"number":15,"instruction":"पेज पर \"SAMRADHI\" वाटरमार्क (Custom Watermark) लगाइए।","marks":1.56,"criteria":[{"rule":"value","target":"pageLayout.watermark","spec":{"regex":"^\\s*samradhi\\s*$"}}],"solution":"1. DESIGN → **Watermark ▾** → **Custom Watermark…**।\n2. **Text watermark** → Text में **SAMRADHI** टाइप करें → **OK**।\n\nजाँच: पेज के बीच में हल्के अक्षरों में SAMRADHI।"},{"number":16,"instruction":"पेज का Size Legal एवं Margins Wide कीजिए।","marks":1.6,"criteria":[{"rule":"value","target":"pageLayout.aspectRatio","spec":{"regex":"^21\\.59 ?/ ?35\\.56$"}},{"rule":"value","target":"pageLayout.padding","spec":["25.4mm 50.8mm 25.4mm 50.8mm"]}],"solution":"1. PAGE LAYOUT → **Size ▾** → **Legal**।\n2. PAGE LAYOUT → **Margins ▾** → **Wide**।\n\nजाँच: पेज Legal (8.5\" × 14\"), बाएँ-दाएँ मार्जिन 2\"।"}]$q$::jsonb);

do $$
declare p record; old record; new_id uuid; q jsonb; question_id uuid;
begin
  for p in select * from new_paper loop
    select v.* into old from public.word_efficiency_tests t join public.word_efficiency_versions v on v.id = t.current_version_id
     where t.language = 'Hindi' and t.title = p.title;
    if old.id is null then raise exception 'Hindi Word % not found', p.title; end if;
    continue when old.working_matter_snapshot = p.matter;
    insert into public.word_efficiency_versions (test_id, version_number, title, language, description, instructions_markdown, delivery_onscreen, delivery_pdf, delivery_realfile,
        student_question_toggle, question_count, maximum_marks, duration_options, passing_marks, created_by, working_matter_snapshot, editor_capabilities, model_answer_snapshot)
    values (old.test_id, (select max(version_number) + 1 from public.word_efficiency_versions where test_id = old.test_id), old.title, old.language, old.description, old.instructions_markdown,
        true, false, false, old.student_question_toggle, jsonb_array_length(p.questions), 25, old.duration_options, old.passing_marks, old.created_by, p.matter, old.editor_capabilities, null)
    returning id into new_id;
    for q in select value from jsonb_array_elements(p.questions) loop
      insert into public.word_efficiency_questions (version_id, question_number, instruction, marks, section, display_order, is_visible, solution)
      values (new_id, (q->>'number')::integer, q->>'instruction', (q->>'marks')::numeric, null, (q->>'number')::integer, true, q->>'solution')
      returning id into question_id;
      insert into public.word_efficiency_grading_rules (version_id, question_id, exact_target, expected_operation, expected_value, allocated_marks, partial_marks, additional_criteria, part_label)
      values (new_id, question_id, 'rule', 'model-answer-match-v2', 'null'::jsonb, (q->>'marks')::numeric, null, q->'criteria', null);
    end loop;
    update public.word_efficiency_tests set current_version_id = new_id, current_version_number = (select version_number from public.word_efficiency_versions where id = new_id),
        auto_publish_results = false, updated_at = now()
     where id = old.test_id;
  end loop;
end $$;

select t.title, t.current_version_number, v.question_count, v.maximum_marks,
       (select count(*) from public.word_efficiency_grading_rules r where r.version_id = v.id) checks
  from public.word_efficiency_tests t join public.word_efficiency_versions v on v.id = t.current_version_id
 where t.language = 'Hindi' and t.title in ('EFFICIENCY TEST 7', 'EFFICIENCY TEST 8') order by t.title;

commit;
